:root{--ink:#17211b;--muted:#69756d;--paper:#f4f1e9;--card:#fffdf8;--brand:#d8552f;--green:#225c48}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.45 system-ui,sans-serif}header{background:var(--green);color:white;padding:20px 5vw;display:flex;align-items:center;justify-content:space-between}h1{margin:0;font-family:Georgia,serif;font-size:30px}nav a{color:#dce9e2;text-decoration:none;margin-left:24px}nav a.active{color:white;border-bottom:2px solid #f1b35e}.wrap{width:min(1200px,92vw);margin:30px auto}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:var(--card);border:1px solid #e2ddd0;border-radius:14px;padding:18px;box-shadow:0 4px 18px #26382d10}.value{font-size:30px;font-weight:750}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:20px;margin-top:22px}h2{font:24px Georgia,serif;margin:0 0 14px}.table-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.table{padding:14px;border-radius:10px;background:#eef2ec;border-left:4px solid var(--green)}.table.occupied{background:#fff0e8;border-color:var(--brand)}.order{padding:12px 0;border-bottom:1px solid #e8e2d7;display:flex;justify-content:space-between}.pill{font-size:12px;text-transform:uppercase;background:#eee5d8;padding:4px 8px;border-radius:20px}@media(max-width:750px){.stats,.table-grid{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}nav a{margin-left:10px}}
